const body = $json.body ?? $json;
const message = String(body.message ?? '').trim();
const childName = String(body.child_name ?? 'friend').trim() || 'friend';
const lower = message.toLowerCase();

let reply = `Hello ${childName}! Let's learn and play together.`;

if (lower.includes('hello') || lower.includes('hi')) {
  reply = `Hello ${childName}! Ready for a fun game?`;
} else if (lower.includes('shape')) {
  reply = 'Shapes are fun. Try matching the same shapes together.';
} else if (lower.includes('color')) {
  reply = 'Colors can help us spot patterns. Can you name your favorite color?';
} else if (lower.includes('maze')) {
  reply = 'The maze game helps with focus and visual tracking. Give it a try.';
} else if (lower.includes('game') || lower.includes('play')) {
  reply = `Let's play, ${childName}! You can try matching, maze, or puzzle games.`;
} else if (lower.includes('help')) {
  reply = 'I can help you choose a game, practice shapes, colors, and cheer you on.';
} else if (lower.includes('bye')) {
  reply = `Bye ${childName}! Come back soon for more fun.`;
} else if (message.length > 0) {
  const options = [
    `Great job, ${childName}! Tell me more.`,
    'That sounds interesting. Do you want to play a game now?',
    'Awesome! We can practice shapes, colors, or visual tracking together.',
    'You are doing well. Let us keep learning step by step.'
  ];
  reply = options[message.length % options.length];
}

return [{ json: { reply, message: { message: reply } } }];
